  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
}

/* Dark-first: dark is the default (:root), light is the override */
:root {
  --radius: 0.5rem;
  --background: oklch(0.12 0 0);
  --foreground: oklch(0.9 0.02 85);
  --card: oklch(0.16 0 0);
  --card-foreground: oklch(0.9 0.02 85);
  --popover: oklch(0.16 0 0);
  --popover-foreground: oklch(0.9 0.02 85);
  --primary: oklch(0.75 0.18 55);
  --primary-foreground: oklch(0.12 0 0);
  --secondary: oklch(0.2 0 0);
  --secondary-foreground: oklch(0.85 0.01 85);
  --muted: oklch(0.2 0 0);
  --muted-foreground: oklch(0.55 0 0);
  --accent: oklch(0.75 0.18 55);
  --accent-foreground: oklch(0.12 0 0);
  --destructive: oklch(0.65 0.22 25);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 12%);
  --ring: oklch(0.75 0.18 55);
  --chart-1: oklch(0.75 0.18 55);
  --chart-2: oklch(0.7 0.15 160);
  --chart-3: oklch(0.65 0.2 300);
  --chart-4: oklch(0.8 0.15 85);
  --chart-5: oklch(0.6 0.2 200);
  --sidebar: oklch(0.14 0 0);
  --sidebar-foreground: oklch(0.9 0.02 85);
  --sidebar-primary: oklch(0.75 0.18 55);
  --sidebar-primary-foreground: oklch(0.12 0 0);
  --sidebar-accent: oklch(0.2 0 0);
  --sidebar-accent-foreground: oklch(0.9 0.02 85);
  --sidebar-border: oklch(1 0 0 / 8%);
  --sidebar-ring: oklch(0.75 0.18 55);
}

.light {
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.65 0.2 50);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.96 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.96 0 0);
  --muted-foreground: oklch(0.45 0 0);
  --accent: oklch(0.65 0.2 50);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.9 0 0);
  --input: oklch(0.9 0 0);
