@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* --- custom animations --- */

@keyframes glow-pulse {
  0%,
  100% {
    text-shadow: 0 0 8px oklch(0.75 0.18 55 / 0.4);
  }
  50% {
    text-shadow:
      0 0 16px oklch(0.75 0.18 55 / 0.6),
      0 0 32px oklch(0.75 0.18 55 / 0.2);
  }
}

.glow-pulse {
  animation: glow-pulse 3s ease-in-out 1s infinite;
}

/* --- Markdown prose styles for assistant messages --- */

.prose-msg {
  line-height: 1.6;
}

.prose-msg h1,
.prose-msg h2,
.prose-msg h3,
.prose-msg h4 {
  font-weight: 700;
  margin-top: 1em;
  margin-bottom: 0.4em;
  line-height: 1.3;
}

.prose-msg h1 { font-size: 1.25em; }
.prose-msg h2 { font-size: 1.1em; }
.prose-msg h3 { font-size: 1em; }
.prose-msg h4 { font-size: 0.95em; }

.prose-msg strong { font-weight: 700; }

.prose-msg code {
  background: oklch(1 0 0 / 6%);
  border-radius: 0.25rem;
  padding: 0.1em 0.35em;
  font-size: 0.85em;
}

.prose-msg pre {
  background: oklch(0.08 0 0);
  border-radius: 0.375rem;
  padding: 0.75em 1em;
  overflow-x: auto;
  margin: 0.75em 0;
}

.prose-msg pre code {
  background: none;
  padding: 0;
  font-size: 0.85em;
}

.prose-msg ul,
.prose-msg ol {
  padding-left: 1.5em;
  margin: 0.5em 0;
}

.prose-msg ul { list-style-type: disc; }
.prose-msg ol { list-style-type: decimal; }

.prose-msg ul ul,
.prose-msg ol ul { list-style-type: circle; }

.prose-msg li { margin: 0.15em 0; }

.prose-msg blockquote {
  border-left: 3px solid oklch(0.75 0.18 55 / 0.5);
  padding-left: 0.75em;
  margin: 0.75em 0;
  color: oklch(0.65 0 0);
}

.prose-msg a {
  color: oklch(0.75 0.18 55);
  text-decoration: underline;
}

.prose-msg table {
  border-collapse: collapse;
  width: 100%;
  margin: 0.75em 0;
  font-size: 0.85em;
}

.prose-msg th,
.prose-msg td {
  border: 1px solid oklch(1 0 0 / 10%);
  padding: 0.35em 0.6em;
  text-align: left;
}

.prose-msg th {
  background: oklch(1 0 0 / 5%);
  font-weight: 600;
}

.prose-msg hr {
  border: none;
  border-top: 1px solid oklch(1 0 0 / 10%);
  margin: 1em 0;
}

.prose-msg img {
  max-width: 100%;
  border-radius: 0.375rem;
}

.prose-msg p {
  margin: 0.4em 0;
}

.prose-msg > :first-child { margin-top: 0; }
.prose-msg > :last-child { margin-bottom: 0; }

/* Light theme overrides */
.light .prose-msg code {
  background: oklch(0 0 0 / 6%);
}

.light .prose-msg pre {
  background: oklch(0.96 0 0);
}

.light .prose-msg th {
  background: oklch(0 0 0 / 5%);
}

.light .prose-msg th,
.light .prose-msg td {
  border-color: oklch(0 0 0 / 10%);
}

.light .prose-msg blockquote {
  color: oklch(0.4 0 0);
}
